/bin/bash -lc "cp src/App.tsx /tmp/App.tsx.before
cat > /tmp/App.tsx.new <<'EOF'
import { useState } from 'react';
import { Button, DropdownMenu } from '@gravity-ui/uikit';

export function App() {
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  return (
    <div style={{ padding: 24 }}>
      <DropdownMenu
        open={isMenuOpen}
        onOpenToggle={setIsMenuOpen}
        size=\"m\"
        items={[
          [
            { text: 'Открыть', action: () => {} },
            { text: 'Дублировать', action: () => {} },
            { text: 'Удалить', action: () => {} },
          ],
        ]}
        renderSwitcher={(props) => (
          <Button {...props} view=\"normal\" size=\"m\">
            Действия
          </Button>
        )}
      />
    </div>
  );
}
EOF
diff -u /tmp/App.tsx.before /tmp/App.tsx.new | sed 's|/tmp/App.tsx|src/App.tsx|g' | git apply
mv /tmp/App.tsx.new src/App.tsx
npm run build"

